package com.enderkidleaf.tvinstaller;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
public class TroubleshootingActivity extends Activity {
    final ExecutorService worker=Executors.newSingleThreadExecutor();final List<View> locked=new ArrayList<>();
    EditText address,command;TextView output,status;ScrollView scroll;Button stop;boolean busy;volatile TroubleshootingCore.Control control;AdbCore.Keys keys;
    interface Work{void run()throws Exception;}
    public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=vertical();root.setPadding(dp(16),dp(16),dp(16),dp(16));root.setBackgroundColor(MainActivity.BG);setContentView(root);root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(dp(16),dp(16)+insets.getSystemWindowInsetTop(),dp(16),dp(16)+insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
        root.addView(text("连接诊断与 ADB 终端",20));address=new EditText(this);address.setSingleLine(true);address.setTextSize(14);address.setHint("目标 IP:端口（默认 5555）");address.setText(getIntent().getStringExtra("target"));root.addView(address);locked.add(address);
        root.addView(text("安卓端直接连接设备，没有电脑端的 ADB 后台服务；修复会重新建立连接。",11));LinearLayout diagnosis=row();diagnosis.addView(button("检查连接",()->{String target=address.getText().toString();run(()->diagnose(target,false));}),weight());diagnosis.addView(button("重新连接",()->{String target=address.getText().toString();run(()->diagnose(target,true));}),weight());root.addView(diagnosis);
        root.addView(text("ADB 终端 · 单次命令，不支持交互。自定义命令可能改动设备数据。",11));LinearLayout quick=row();quick.addView(button("设备型号",()->command.setText("getprop ro.product.model")),weight());quick.addView(button("存储空间",()->command.setText("df -h /data")),weight());quick.addView(button("系统日志",()->command.setText("logcat -d -t 200")),weight());root.addView(quick);
        command=new EditText(this);command.setSingleLine(true);command.setTextSize(13);command.setTypeface(Typeface.MONOSPACE);command.setText("getprop ro.product.model");command.setHint("设备 shell 命令");root.addView(command);locked.add(command);
        LinearLayout actions=row();actions.addView(button("运行",()->{String target=address.getText().toString(),value=command.getText().toString();run(()->terminal(target,value));}),weight());actions.addView(button("本机网络",()->run(()->{for(AdbCore.Lan lan:AdbCore.Lan.current())append(lan.toString());})),weight());stop=new Button(this);stop.setText("停止");stop.setEnabled(false);stop.setOnClickListener(v->{TroubleshootingCore.Control c=control;if(c!=null)c.stop();});actions.addView(stop,weight());root.addView(actions);
        scroll=new ScrollView(this);output=text("",11);output.setTypeface(Typeface.MONOSPACE);output.setTextIsSelectable(true);String initial=getIntent().getStringExtra("output");if(initial!=null)output.setText(initial);scroll.addView(output);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));status=text("输入目标地址后检查连接，或运行排障命令。",12);root.addView(status);
        LinearLayout exports=row();Button copy=new Button(this);copy.setText("复制");copy.setOnClickListener(v->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("ADB排障记录",output.getText()));});exports.addView(copy,weight());Button export=new Button(this);export.setText("导出");locked.add(export);export.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("text/plain");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"ADB排障记录.txt");startActivityForResult(intent,401);});exports.addView(export,weight());exports.addView(button("清空",()->output.setText("")),weight());root.addView(exports);
    }
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}LinearLayout vertical(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}LinearLayout row(){return new LinearLayout(this);}LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,-2,1);}
    TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(MainActivity.INK);v.setPadding(0,dp(4),0,dp(4));return v;}
    Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(12);b.setOnClickListener(v->action.run());locked.add(b);return b;}
    void ui(Runnable action){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())action.run();});}void append(String value){ui(()->{String text=output.getText()+value+"\n";output.setText(text.length()>256*1024?text.substring(text.length()-120000):text);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));});}void note(String value){ui(()->status.setText(value));}
    void run(Work work){if(busy)return;busy=true;control=new TroubleshootingCore.Control();for(View v:locked)v.setEnabled(false);stop.setEnabled(true);getWindow().getDecorView().setKeepScreenOn(true);worker.submit(()->{try{if(keys==null)keys=AdbCore.Keys.load(new File(getFilesDir(),"adb-trust"));work.run();}catch(Exception e){String message=AdbCore.friendly(e.getMessage());note(message);append(message);}finally{control=null;ui(()->{busy=false;stop.setEnabled(false);for(View v:locked)v.setEnabled(true);getWindow().getDecorView().setKeepScreenOn(false);});}});}
    void diagnose(String input,boolean repair)throws Exception{AdbCore.Endpoint target=AdbCore.Endpoint.parse(input);append("\n["+new Date()+"] 目标："+target.address());if(repair)append("重新建立直连，不更改设备设置，不清除授权密钥。");boolean open=TroubleshootingCore.probe(target,this::append);append(open?"TCP 端口可访问。":"TCP 端口不可访问：检查电源、地址、端口、网络调试或局域网隔离。");if(control.cancelled){note("操作已停止。");return;}TroubleshootingCore.Result result=TroubleshootingCore.execute(target,keys,"echo ADB_DIAG_OK; getprop ro.product.model; getprop ro.build.version.release",control,this::note,text->{},20000,256*1024);append(result.text);String message=result.success&&result.text.startsWith("ADB_DIAG_OK")?"连接正常，设备授权与命令通道均可用。":result.status;append(message);note(message);}
    void terminal(String input,String source)throws Exception{AdbCore.Endpoint target=AdbCore.Endpoint.parse(input);String value=TroubleshootingCore.validate(source);final String[] prefix={""};FutureTask<Void> snapshot=new FutureTask<>(()->{append("\n["+new Date()+"] "+target.address()+" $ "+value);prefix[0]=output.getText().toString();return null;});runOnUiThread(snapshot);snapshot.get();TroubleshootingCore.Control current=control;note("正在执行，可点击停止。");TroubleshootingCore.Result result=TroubleshootingCore.execute(target,keys,value,current,this::note,text->ui(()->{if(busy&&control==current){output.setText(prefix[0]+text);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}}));ui(()->{output.setText(prefix[0]+result.text+"\n["+result.status+"]\n");scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));});note(result.status);}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=401||result!=RESULT_OK||data==null||data.getData()==null)return;final byte[] bytes=output.getText().toString().getBytes(StandardCharsets.UTF_8);final android.net.Uri uri=data.getData();if(busy){note("请先停止命令再导出。");return;}run(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法导出排障记录。");out.write(bytes);}note("排障记录已导出。");});}
    public void onBackPressed(){if(busy){TroubleshootingCore.Control c=control;if(c!=null)c.stop();note("正在停止，完成后可返回。");}else super.onBackPressed();}
    protected void onDestroy(){super.onDestroy();TroubleshootingCore.Control c=control;if(c!=null)c.stop();worker.shutdownNow();}
}
